-- Adds the three new moulded candles and the three candle sets as DRAFTS (customers cannot see them). 26 Nov 2026. Run once in Supabase -> SQL editor.
-- Christmas Tree (MC-013), Teddy (MC-014) and Evening Ember / Classic Pillar (MC-015). The sets are Float & Bloom Trio (ST-001), Moulded Six (ST-002), Mini Bubble Trio (ST-003); set stock starts at 0, so set the real count in Owner view. Add their photos in Owner view -> Photos & videos, then press Publish.
-- Safe to run again: it does nothing if a product already exists. It does not touch any other product, stock, photos, orders or settings.
begin;
-- If you ran the earlier version, this brings the three candle prices to the locked ones (299, 99, 399). Only the price changes.
update products set data = jsonb_set(data, '{variants,0,price}', '299'::jsonb) where id = 'bnt-prd-mc-013';
update products set data = jsonb_set(data, '{variants,0,price}', '99'::jsonb) where id = 'bnt-prd-mc-014';
update products set data = jsonb_set(data, '{variants,0,price}', '399'::jsonb) where id = 'bnt-prd-mc-015';
commit;

select id, data->>'name' as name, data->'variants'->0->>'price' as price, live from products where id in ('bnt-prd-mc-013','bnt-prd-mc-014','bnt-prd-mc-015','bnt-prd-st-001','bnt-prd-st-002','bnt-prd-st-003');
